    ctx.moveTo(cx, cy - h + 0.5);
    ctx.lineTo(cx + w - 0.5, cy);
    ctx.lineTo(cx, cy + h - 0.5);
    ctx.lineTo(cx - w + 0.5, cy);
    ctx.closePath();
    ctx.stroke();
    ctx.strokeStyle = 'rgba(255,255,255,0.045)';
    ctx.beginPath();
    ctx.moveTo(cx, cy - h + 1);
    ctx.lineTo(cx + w - 1, cy);
    ctx.stroke();
    ctx.restore();
