403:   // ------------------------------------------------------------
404:   // WEATHER
405:   // ------------------------------------------------------------
406:   makeWeather(kind) {
407:     const n = WEATHER_COUNT[kind] || 24;
408:     this.particles = [];
409:     for (let i = 0; i < n; i++) {
410:       this.particles.push({
411:         x: Math.random() * this.width,
412:         y: Math.random() * this.height,
413:         vx: (Math.random() - 0.5) * 12,
414:         vy: 8 + Math.random() * 26,
415:         size: 1 + Math.random() * 2,
416:         phase: Math.random() * Math.PI * 2,
417:         speed: 0.4 + Math.random() * 1.6,
418:         alpha: 0.25 + Math.random() * 0.5
419:       });
420:     }
421:     this.weatherKind = kind;
422:   }
423: 
424:   updateWeather(dt) {
425:     const kind = this.weatherKind;
426:     for (const p of this.particles) {
427:       p.phase += dt * p.speed;
428:       if (kind === 'embers') {
429:         p.y -= (14 + p.speed * 22) * dt;
430:         p.x += Math.sin(p.phase * 2) * 14 * dt;
431:       } else if (kind === 'snow') {
432:         p.y += p.vy * dt;
433:         p.x += Math.sin(p.phase) * 16 * dt;
434:       } else if (kind === 'sand') {
435:         p.x += (40 + p.speed * 45) * dt;
436:         p.y += Math.sin(p.phase) * 8 * dt;
437:       } else if (kind === 'stars') {
438:         // static twinkle
439:       } else if (kind === 'mist') {
440:         p.x += (4 + p.speed * 4) * dt;
441:         p.y += Math.sin(p.phase) * 2 * dt;
442:       } else {
443:         p.y += p.vy * dt * 0.7;
444:         p.x += Math.sin(p.phase * 1.4) * 20 * dt;
445:       }
446:       if (p.y > this.height + 20) { p.y = -20; p.x = Math.random() * this.width; }
447:       if (p.y < -30) { p.y = this.height + 10; p.x = Math.random() * this.width; }
448:       if (p.x > this.width + 20) p.x = -20;
449:       if (p.x < -20) p.x = this.width + 20;
450:     }
451:   }
452: 
453:   drawWeather(ctx) {
454:     const kind = this.weatherKind;
455:     const pal = this.world.region.palette;
456:     ctx.save();
457:     if (kind === 'leaves') {
458:       for (const p of this.particles) {
459:         ctx.globalAlpha = p.alpha;
460:         ctx.fillStyle = Math.sin(p.phase) > 0 ? pal.accent : '#d5a44c';
461:         ctx.fillRect(p.x, p.y, p.size + 1, p.size);
462:       }
463:     } else if (kind === 'embers') {
464:       for (const p of this.particles) {
465:         ctx.globalAlpha = p.alpha * (0.7 + Math.sin(p.phase * 2) * 0.3);
466:         ctx.fillStyle = Math.sin(p.phase) > 0 ? '#ffb23e' : '#ff5a3c';
467:         ctx.fillRect(p.x, p.y, p.size, p.size);
468:       }
469:     } else if (kind === 'spores') {
470:       for (const p of this.particles) {
471:         ctx.globalAlpha = p.alpha * (0.5 + Math.sin(p.phase) * 0.5);
472:         ctx.fillStyle = '#c9a0ff';
473:         ctx.fillRect(p.x, p.y, p.size, p.size);
474:         ctx.globalAlpha *= 0.4;
475:         ctx.fillRect(p.x - 1, p.y - 1, p.size + 2, p.size + 2);
476:       }
477:     } else if (kind === 'snow') {
478:       for (const p of this.particles) {
479:         ctx.globalAlpha = p.alpha;
480:         ctx.fillStyle = '#f2fbff';
481:         ctx.fillRect(p.x, p.y, p.size, p.size);
482:       }
483:     } else if (kind === 'sand') {
484:       for (const p of this.particles) {
485:         ctx.globalAlpha = p.alpha * 0.6;
486:         ctx.fillStyle = '#f0d79a';
487:         ctx.fillRect(p.x, p.y, p.size + 2, 1);
488:       }
489:     } else if (kind === 'stars') {
490:       for (const p of this.particles) {
491:         ctx.globalAlpha = 0.25 + Math.abs(Math.sin(p.phase)) * 0.6;
492:         ctx.fillStyle = Math.sin(p.phase * 2) > 0 ? '#fff4c4' : '#c9b4ff';
493:         ctx.fillRect(p.x, p.y, p.size, p.size);
494:       }
495:     } else if (kind === 'mist') {
496:       for (const p of this.particles) {
497:         ctx.globalAlpha = 0.05 + p.alpha * 0.05;
498:         ctx.fillStyle = '#b7d4ea';
499:         ctx.beginPath();
500:         ctx.ellipse(p.x, p.y, 90 + p.size * 25, 22 + p.size * 5, 0, 0, Math.PI * 2);
501:         ctx.fill();
502:       }
503:     }
504:     ctx.restore();
505:   }
506: 
507:   // ------------------------------------------------------------
508:   // MAIN RENDER
509:   // ------------------------------------------------------------
510:   render(game, dt) {
511:     const ctx = this.ctx;
512:     this.time += dt;
513:     this.updateWeather(dt);
514:     this.updateDust(dt);
515:     const world = this.world;
516:     if (!world || !game.player) return;
517:     const z = this.viewZoom;
518:     const vw = this.viewW(), vh = this.viewH();
519: 
520:     // camera follow (still smoothly centered on the player)
521:     const p = this.iso(game.player.x, game.player.y);
522:     this.camTarget.x = lerp(this.camTarget.x, p.x - vw / 2, 0.18);
523:     this.camTarget.y = lerp(this.camTarget.y, p.y - vh / 2 - 34, 0.18);
524:     this.clampCamera(this.camTarget);
525:     this.cam.x = lerp(this.cam.x, this.camTarget.x, 0.22);
526:     this.cam.y = lerp(this.cam.y, this.camTarget.y, 0.22);
527:     if (Math.abs(this.cam.x - this.camTarget.x) < 0.05) this.cam.x = this.camTarget.x;
528:     if (Math.abs(this.cam.y - this.camTarget.y) < 0.05) this.cam.y = this.camTarget.y;
529: 
530:     // ---- sky backdrop (screen space) ----
531:     ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
532:     ctx.imageSmoothingEnabled = false;
533:     const pal = world.region.palette;
534:     const bg = ctx.createLinearGradient(0, 0, 0, this.height);
535:     bg.addColorStop(0, pal.sky);
536:     bg.addColorStop(1, shade(pal.sky, -0.12));
537:     ctx.fillStyle = bg;
538:     ctx.fillRect(0, 0, this.width, this.height);
539: 
540:     // ---- world (zoomed slightly out to show more of the surrounding land) ----
541:     ctx.setTransform(this.dpr * z, 0, 0, this.dpr * z, 0, 0);
542:     // ground is the only pre-rendered bitmap — smooth its downscale so the pixel art stays clean
543:     ctx.imageSmoothingEnabled = true;
544:     if ('imageSmoothingQuality' in ctx) ctx.imageSmoothingQuality = 'high';
545:     ctx.drawImage(this.ground, -Math.round(this.cam.x), -Math.round(this.cam.y));
546:     ctx.imageSmoothingEnabled = false;
547: 
548:     this.drawWaterFX(ctx);
549: 
550:     // lights beneath objects
551:     this.drawGroundLights(ctx, world);
552: 
553:     // player running dust behind entities
554:     this.spawnDust(game);
555:     this.drawDust(ctx);
556: 
557:     // collect drawables
558:     const drawables = [];
559:     const margin = 260;
560:     const visible = (sx, sy) => sx > -margin && sx < vw + margin && sy > -margin - 100 && sy < vh + margin;
561: 
562:     for (const prop of world.props) {
563:       const s = this.worldToView(prop.x, prop.y);
564:       if (visible(s.x, s.y - 80)) drawables.push({ z: prop.x + prop.y, read: () => this.drawPropSprite(ctx, prop, s) });
565:     }
566:     for (const node of world.nodes) {
567:       if (node.respawnAt > Date.now()) continue;
568:       const s = this.worldToView(node.x, node.y);
569:       if (visible(s.x, s.y)) drawables.push({ z: node.x + node.y, read: () => this.drawNodeSprite(ctx, node, s) });
570:     }
571:     for (const h of world.hidden) {
572:       if (h.opened) continue;
573:       const s = this.worldToView(h.x, h.y);
574:       if (visible(s.x, s.y)) drawables.push({ z: h.x + h.y, read: () => this.drawChestSprite(ctx, h, s) });
575:     }
576:     for (const npc of world.npcs) {
577:       const s = this.worldToView(npc.x, npc.y);
578:       if (visible(s.x, s.y)) drawables.push({ z: npc.x + npc.y, read: () => this.drawNpcSprite(ctx, npc, s, game) });
579:     }
580:     for (const enemy of world.enemies) {
581:       if (!enemy.alive) continue;
582:       const s = this.worldToView(enemy.x, enemy.y);
583:       if (visible(s.x, s.y)) drawables.push({ z: enemy.x + enemy.y + 0.01, read: () => this.drawEnemySprite(ctx, enemy, s, game) });
584:     }
585:     if (game.groundLoot) {
586:       for (const loot of game.groundLoot) {
587:         const s = this.worldToView(loot.x, loot.y);
588:         if (visible(s.x, s.y)) drawables.push({ z: loot.x + loot.y + 0.005, read: () => this.drawLootSprite(ctx, loot, s) });
589:       }
590:     }
591:     // player
592:     const ps = this.worldToView(game.player.x, game.player.y);
593:     drawables.push({ z: game.player.x + game.player.y + 0.02, read: () => this.drawPlayerSprite(ctx, game, ps) });
594: 
595:     drawables.sort((a, b) => a.z - b.z);
596:     for (const d of drawables) d.read();
597: 
598:     // target ring under current target
599:     if (game.target && game.target.alive) this.drawTargetRing(ctx, game.target);
600:     if (game.interactTarget) this.drawInteractRing(ctx, game.interactTarget);
601: 
602:     // pets (drawn above world)
603:     if (game.state.char.petActive && game.state.petDef()) {
604:       const off = this.iso(game.player.x, game.player.y);
605:       ctx.save();
606:       const S = this.spriteScale();
607:       ctx.translate(ps.x + 28, ps.y - 20);
608:       ctx.scale(S * 0.8, S * 0.8);
609:       drawPet(ctx, game.state.petDef(), this.time);
610:       ctx.restore();
611:     }
612: 
613:     // skill / combat effects and projectiles
614:     this.drawEffects(ctx, game);
615: 
616:     // ---- screen-space atmosphere ----
617:     ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
618: 
619:     // soft light shafts over the forests
620:     if (['greendale', 'venomwood', 'ironcrag'].includes(world.regionId)) this.drawSunShafts(ctx);
621: 
622:     // weather
623:     this.drawWeather(ctx);
624: 
625:     // ambient fog / region tint
626:     ctx.save();
627:     const fog = ctx.createRadialGradient(this.width / 2, this.height / 2, Math.min(this.width, this.height) * 0.2, this.width / 2, this.height / 2, Math.max(this.width, this.height) * 0.76);
628:     fog.addColorStop(0, pal.fog);
629:     fog.addColorStop(1, 'rgba(5,4,10,0.46)');
630:     ctx.fillStyle = fog;
631:     ctx.fillRect(0, 0, this.width, this.height);
632:     ctx.restore();
633: 
634:     if (world.mode === 'dungeon') {
635:       ctx.fillStyle = 'rgba(8,4,14,0.16)';
636:       ctx.fillRect(0, 0, this.width, this.height);
637:     }
638: 
639:     // minimap occasionally
640:     const now = performance.now();
641:     if (this.minimapCanvas && now - this.lastMinimap > 220) {
642:       this.lastMinimap = now;
643:       this.drawMinimap(this.minimapCanvas, game);
644:     }
645:   }
