647:   // ------------------------------------------------------------
648:   // RUNNING DUST
649:   // ------------------------------------------------------------
650:   spawnDust(game) {
651:     if (!game.player.moving || !this.world) return;
652:     this._dustAcc = (this._dustAcc || 0) + (this._dt || 0);
653:     if (this._dustAcc < 0.14) return;
654:     this._dustAcc = 0;
655:     const p = this.iso(game.player.x, game.player.y);
656:     this.dust.push({
657:       x: p.x - this.cam.x + (Math.random() - 0.5) * 8,
658:       y: p.y - this.cam.y + 2,
659:       vx: (Math.random() - 0.5) * 14,
660:       vy: -6 - Math.random() * 8,
661:       life: 0.55 + Math.random() * 0.3,
662:       maxLife: 0.85,
663:       size: 2 + Math.random() * 2
664:     });
665:   }
666: 
667:   updateDust(dt) {
668:     this._dt = dt;
669:     for (const d of this.dust) {
670:       d.life -= dt;
671:       d.x += d.vx * dt;
672:       d.y += d.vy * dt;
673:       d.vy += 20 * dt;
674:     }
675:     this.dust = this.dust.filter(d => d.life > 0);
676:   }
677: 
678:   drawDust(ctx) {
679:     const pal = this.world.region.palette;
680:     const base = shade(pal.ground1, 0.22);
681:     for (const d of this.dust) {
682:       const a = clamp(d.life / d.maxLife, 0, 1) * 0.3;
683:       ctx.globalAlpha = a;
684:       ctx.fillStyle = base;
685:       const s = d.size * (1 + (1 - d.life / d.maxLife));
686:       ctx.fillRect(d.x - s / 2, d.y - s / 2, s, s * 0.8);
687:     }
688:     ctx.globalAlpha = 1;
689:   }
690: 
691:   drawSunShafts(ctx) {
692:     const t = this.time;
693:     ctx.save();
694:     ctx.globalCompositeOperation = 'lighter';
695:     for (let i = 0; i < 3; i++) {
696:       const x = this.width * (0.18 + i * 0.3) + Math.sin(t * 0.15 + i * 2) * 26;
697:       const g = ctx.createLinearGradient(x, 0, x + 120, this.height);
698:       g.addColorStop(0, 'rgba(255,236,170,0.075)');
699:       g.addColorStop(0.75, 'rgba(255,220,140,0.02)');
700:       g.addColorStop(1, 'rgba(255,220,140,0)');
701:       ctx.fillStyle = g;
702:       ctx.beginPath();
703:       ctx.moveTo(x, -10);
704:       ctx.lineTo(x + 95, -10);
705:       ctx.lineTo(x + 230, this.height + 10);
706:       ctx.lineTo(x + 70, this.height + 10);
707:       ctx.closePath();
708:       ctx.fill();
709:     }
710:     ctx.restore();
711:   }
712: 
713:   spriteScale() {
714:     const base = Math.min(this.width, this.height) < 620 ? 2.0 : 2.35;
715:     return base;
716:   }
717: 
718:   // ------------------------------------------------------------
719:   // OBJECT RENDERING
720:   // ------------------------------------------------------------
721:   drawShadow(ctx, sx, sy, w, alpha = 0.28) {
722:     ctx.save();
723:     const glow = ctx.createRadialGradient(sx, sy + 2, 0, sx, sy + 2, w * 1.15);
724:     glow.addColorStop(0, `rgba(4,3,10,${alpha})`);
725:     glow.addColorStop(0.7, `rgba(4,3,10,${alpha * 0.62})`);
726:     glow.addColorStop(1, 'rgba(4,3,10,0)');
727:     ctx.fillStyle = glow;
728:     ctx.beginPath();
729:     ctx.ellipse(sx, sy + 2, w * 1.15, w * 0.48, 0, 0, Math.PI * 2);
730:     ctx.fill();
731:     ctx.globalAlpha = Math.min(0.42, alpha + 0.08);
732:     ctx.fillStyle = '#08060d';
733:     ctx.beginPath();
734:     ctx.ellipse(sx, sy + 1, w * 0.78, w * 0.27, 0, 0, Math.PI * 2);
735:     ctx.fill();
736:     ctx.restore();
737:   }
738: 
739:   drawPropSprite(ctx, prop, s) {
740:     const S = this.spriteScale() * (prop.scale || 1);
741:     const sc = this.spriteScale();
742:     const shadowW = prop.type === 'house' ? 36 : prop.type === 'tent' ? 26 : prop.kind === 'tree' ? 20 : 12;
743:     this.drawShadow(ctx, s.x, s.y, shadowW * sc * 0.55, prop.type === 'house' ? 0.35 : 0.22);
744:     ctx.save();
745:     ctx.translate(s.x, s.y);
746:     ctx.scale(S, S);
747:     drawProp(ctx, { ...prop, scale: 1 }, this.time, this.biomeStyle());
748:     ctx.restore();
749: 
750:     // prop light sources (flicker)
751:     if (['campfire', 'brazier', 'forge', 'crystal', 'void_crystal', 'star_well', 'lava_rock'].includes(prop.kind)) {
752:       const fl = 0.92 + Math.sin(this.time * 6 + s.x * 0.11) * 0.07;
753:       this.addLight(ctx, s.x, s.y - 12 * sc, (prop.kind === 'forge' ? 120 : 80) * fl, prop.kind === 'crystal' || prop.kind === 'void_crystal' ? '#8fe2ff' : '#ff8a3c');
754:     }
755:   }
756: 
757:   drawNodeSprite(ctx, node, s) {
758:     const S = this.spriteScale();
759:     this.drawShadow(ctx, s.x, s.y, 12, 0.2);
760:     ctx.save();
761:     ctx.translate(s.x, s.y);
762:     ctx.scale(S, S);
763:     drawProp(ctx, { ...node, kind: 'node', scale: node.scale || 1 }, this.time, this.biomeStyle());
764:     ctx.restore();
765:     this.addLight(ctx, s.x, s.y - 10, 45, '#b6ff9a', 0.25);
766:     // sparkle
767:     const t = this.time * 2 + node.x;
768:     ctx.save();
769:     ctx.globalAlpha = 0.5 + Math.sin(t) * 0.3;
770:     ctx.fillStyle = '#e8ffcc';
771:     ctx.fillRect(s.x + Math.sin(t * 1.7) * 12, s.y - 24 + Math.cos(t * 1.3) * 6, 2, 2);
772:     ctx.restore();
773:   }
774: 
775:   drawLootSprite(ctx, loot, s) {
776:     const item = loot.item;
777:     const isStone = item.kind === 'stone';
778:     const isMat = item.kind === 'material';
779:     const color = isStone ? '#ffd166' : isMat ? '#a8e07a' : (RARITIES[item.rarity]?.color || '#ffffff');
780:     const bob = Math.sin(this.time * 4 + (loot.bob || 0)) * 3;
781:     const x = s.x;
782:     const y = s.y + bob;
783:     ctx.save();
784:     // pickup beam
785:     ctx.globalAlpha = 0.18 + Math.sin(this.time * 5 + (loot.bob || 0)) * 0.06;
786:     const g = ctx.createLinearGradient(x, y - 50, x, y);
787:     g.addColorStop(0, 'rgba(255,255,255,0)');
788:     g.addColorStop(1, this.hexAlpha(color, 0.6));
789:     ctx.fillStyle = g;
790:     ctx.fillRect(x - 4, y - 50, 8, 50);
791:     ctx.globalAlpha = 1;
792:     // glow
793:     this.addLight(ctx, x, y - 10, 28, color, 0.18);
794:     // pouch / gem
795:     if (isMat) {
796:       ctx.fillStyle = '#3f4a32';
797:       ctx.fillRect(x - 5, y - 11, 10, 9);
798:       ctx.fillStyle = color;
799:       ctx.fillRect(x - 3, y - 13, 6, 5);
800:       ctx.fillStyle = '#e8ffd0';
801:       ctx.fillRect(x - 1, y - 12, 2, 2);
802:     } else if (isStone) {
803:       ctx.fillStyle = '#2b2130';
804:       ctx.fillRect(x - 5, y - 10, 10, 8);
805:       ctx.fillStyle = color;
806:       ctx.fillRect(x - 3, y - 13, 6, 6);
807:       ctx.fillStyle = '#fff6d0';
808:       ctx.fillRect(x - 1, y - 12, 2, 2);
809:     } else {
810:       ctx.fillStyle = '#2b2130';
811:       ctx.fillRect(x - 6, y - 11, 12, 9);
812:       ctx.fillStyle = this.hexAlpha(color, 0.9);
813:       ctx.fillRect(x - 4, y - 12, 8, 3);
814:       ctx.fillStyle = '#4a3a2a';
815:       ctx.fillRect(x - 6, y - 4, 12, 2);
816:       ctx.fillStyle = color;
817:       ctx.fillRect(x - 1, y - 8, 2, 2);
818:     }
819:     // sparkle
820:     ctx.globalAlpha = 0.6 + Math.sin(this.time * 6 + (loot.bob || 0)) * 0.4;
821:     ctx.fillStyle = '#fff8d8';
822:     ctx.fillRect(x + 8, y - 20, 2, 2);
823:     ctx.fillRect(x - 10, y - 15, 1, 1);
824:     ctx.restore();
825:   }
826: 
827:   drawChestSprite(ctx, h, s) {    const S = this.spriteScale();
828:     this.drawShadow(ctx, s.x, s.y, 12, 0.22);
829:     ctx.save();
830:     ctx.translate(s.x, s.y);
831:     ctx.scale(S, S);
832:     drawProp(ctx, { ...h, type: 'chest', kind: 'chest', scale: 1 }, this.time, this.biomeStyle());
833:     ctx.restore();
834:     this.addLight(ctx, s.x, s.y - 10, 55, '#ffdf37', 0.28);
835:     const t = this.time * 2.4 + h.x;
836:     ctx.save();
837:     ctx.globalAlpha = 0.6 + Math.sin(t) * 0.3;
838:     ctx.fillStyle = '#fff3a8';
839:     ctx.fillRect(s.x - 10 + Math.sin(t) * 3, s.y - 34 + Math.cos(t * 1.3) * 4, 2, 2);
840:     ctx.fillRect(s.x + 8 + Math.cos(t) * 3, s.y - 28 + Math.sin(t * 1.7) * 4, 2, 2);
841:     ctx.restore();
842:   }
843: 
844:   drawNpcSprite(ctx, npc, s, game) {
845:     const S = this.spriteScale();
846:     this.drawShadow(ctx, s.x, s.y, 10, 0.24);
847:     ctx.save();
848:     ctx.translate(s.x, s.y);
849:     ctx.scale(S, S);
850:     drawNpc(ctx, npc, this.time);
851:     ctx.restore();
852: 
853:     // name and role
854:     if (game.state.data.settings.showNames) {
855:       this.drawWorldLabel(ctx, npc.name, s.x, s.y - 104, '#f0d89a', 10);
856:     }
857:     const state = game.state;
858:     let marker = null;
859:     if (npc.role === 'Quest Keeper') {
860:       const available = state.availableQuests().some(q => q.region === npc.region);
861:       const complete = state.data.quests.active.some(a => {
862:         const q = game.questDef(a.id);
863:         return q && q.region === npc.region && state.isQuestComplete(q);
864:       });
865:       if (available) marker = '!';
866:       else if (complete) marker = '?';
867:     }
868:     if (marker) {
869:       const y = s.y - 126 + Math.sin(this.time * 2.5) * 3;
870:       ctx.save();
871:       ctx.font = 'bold 22px Georgia, serif';
872:       ctx.textAlign = 'center';
873:       ctx.lineWidth = 4;
874:       ctx.strokeStyle = 'rgba(12,8,18,0.9)';
875:       ctx.strokeText(marker, s.x, y);
876:       ctx.fillStyle = marker === '!' ? '#ffd15c' : '#7dffc1';
877:       ctx.fillText(marker, s.x, y);
878:       ctx.restore();
879:     }
880:   }
881: 
882:   drawEnemySprite(ctx, enemy, s, game) {
883:     const S = this.spriteScale();
884:     const def = enemy.def;
885:     const shadowW = def.boss ? 30 : enemy.elite ? 16 : 12;
886:     this.drawShadow(ctx, s.x, s.y, shadowW, def.boss ? 0.4 : 0.25);
887:     if (def.boss) {
888:       this.addLight(ctx, s.x, s.y - 30, 140, def.color, 0.18);
889:       // boss aura ring
890:       ctx.save();
891:       ctx.globalAlpha = 0.25 + Math.sin(this.time * 2) * 0.08;
892:       ctx.strokeStyle = def.color;
893:       ctx.lineWidth = 2;
894:       ctx.beginPath();
895:       ctx.ellipse(s.x, s.y, 46, 18, 0, 0, Math.PI * 2);
896:       ctx.stroke();
897:       ctx.restore();
898:     }
899:     if (enemy.elite) this.addLight(ctx, s.x, s.y - 20, 50, '#ffd166', 0.16);
900:     ctx.save();
901:     ctx.translate(s.x, s.y);
902:     ctx.scale(S, S);
903:     drawEnemy(ctx, enemy, this.time);
904:     ctx.restore();
905: 
906:     // hp bar
907:     const w = def.boss ? 92 : enemy.elite ? 56 : 40;
908:     const y = s.y - (def.boss ? 120 : enemy.elite ? 92 : 74) * (enemy.scale || 1) / 1.2;
909:     this.drawBar(ctx, s.x - w / 2, y, w, 4, enemy.hp / enemy.maxHp, def.boss ? '#ff5a5a' : enemy.elite ? '#ffd166' : '#65d67a');
910:     if (game.state.data.settings.showNames) {
911:       const nm = (enemy.elite ? 'Elite ' : '') + def.name + (def.boss ? '  ☠' : '');
912:       this.drawWorldLabel(ctx, nm, s.x, y - 5, def.boss ? '#ffb08a' : enemy.elite ? '#ffd166' : '#e6e2d8', def.boss ? 11 : 9);
913:     }
914:   }
915: 
916:   drawPlayerSprite(ctx, game, s) {
917:     const state = game.state;
918:     const c = state.char;
919:     const S = this.spriteScale();
920:     const eq = state.data.equipped;
921:     const wings = state.wingsDef();
922:     const mount = state.mountDef();
923:     const cosmetic = state.costumePalette();
924: 
925:     // equipment aura
926:     const aura = this.equipmentAura(state);
927:     if (aura) {
928:       this.addLight(ctx, s.x, s.y - 45, 80 + aura.strength * 20, aura.color, 0.13 + aura.strength * 0.05);
929:       ctx.save();
930:       ctx.globalAlpha = 0.25 + aura.strength * 0.08;
931:       ctx.strokeStyle = aura.color;
932:       ctx.lineWidth = 1.5;
933:       ctx.beginPath();
934:       ctx.ellipse(s.x, s.y, 26 + aura.strength * 5, 10 + aura.strength * 2, 0, 0, Math.PI * 2);
935:       ctx.stroke();
936:       ctx.restore();
937:     }
938:     this.drawShadow(ctx, s.x, s.y, mount ? 24 : 13, mount ? 0.32 : 0.26);
939:     // A restrained ground sigil anchors the hero against busy terrain.
940:     ctx.save();
941:     ctx.globalAlpha = 0.18 + (aura ? aura.strength * 0.025 : 0);
942:     ctx.strokeStyle = aura?.color || '#e6c46a';
943:     ctx.lineWidth = 1;
944:     ctx.setLineDash([3, 4]);
945:     ctx.beginPath();
946:     ctx.ellipse(s.x, s.y + 1, mount ? 28 : 18, mount ? 9 : 6, 0, 0, Math.PI * 2);
947:     ctx.stroke();
948:     ctx.restore();
949: 
950:     // arcane sigil while casting
951:     if (game.player.casting) {
952:       const sigC = c.classId === 'mage' ? '#79d6ff' : '#ffb23e';
953:       ctx.save();
954:       ctx.globalAlpha = 0.4 + Math.sin(this.time * 9) * 0.15;
955:       ctx.strokeStyle = sigC;
956:       ctx.lineWidth = 1.4;
957:       ctx.beginPath();
958:       ctx.ellipse(s.x, s.y, 16, 7, 0, 0, Math.PI * 2);
959:       ctx.stroke();
960:       ctx.globalAlpha *= 0.7;
961:       ctx.beginPath();
962:       ctx.ellipse(s.x, s.y, 9, 4, 0, 0, Math.PI * 2);
963:       ctx.stroke();
964:       const spin = this.time * 6;
965:       for (let i = 0; i < 6; i++) {
966:         const a = spin + i * Math.PI / 3;
967:         ctx.fillStyle = sigC;
968:         ctx.fillRect(s.x + Math.cos(a) * 16, s.y + Math.sin(a) * 7, 1.5, 1.5);
969:       }
970:       ctx.restore();
971:     }
972: 
973:     ctx.save();
974:     ctx.translate(s.x, s.y);
975:     ctx.scale(S, S);
976:     drawCharacter(ctx, {
977:       faction: c.faction, classId: c.classId, gender: c.gender,
978:       hairStyle: c.hair, hairColor: state.hairColorHex(), eyeColor: state.eyeColorHex(),
979:       equipment: eq, wings, mount, cosmetic,
980:       time: this.time, moving: game.player.moving,
981:       facing: game.player.facing || 1,
982:       attack: game.player.attackAnim,
983:       casting: game.player.casting,
984:       aura: aura,
985:       weaponFx: state.weaponFxDef()
986:     });
987:     ctx.restore();
988: 
989:     // weapon fx particles
990:     if (state.weaponFxDef()) {
991:       const fx = state.weaponFxDef();
992:       ctx.save();
993:       ctx.globalAlpha = 0.6;
994:       for (let i = 0; i < 3; i++) {
995:         const a = this.time * 2 + i * 2.1;
996:         ctx.fillStyle = fx.color;
997:         ctx.fillRect(s.x + Math.cos(a) * 18, s.y - 40 + Math.sin(a * 1.3) * 22, 2, 2);
998:       }
999:       ctx.restore();
1000:     }
1001: 
1002:     // own name / title
1003:     if (state.data.settings.showNames) {
1004:       this.drawWorldLabel(ctx, `${c.name}  ·  Lv ${c.level}`, s.x, s.y - (mount ? 128 : 112), '#f5e6bd', 10);
1005:     }
1006: 
1007:     // interact prompt
1008:     if (game.interactLabel) {
1009:       const y = s.y - (mount ? 150 : 132) + Math.sin(this.time * 3) * 2;
1010:       ctx.save();
1011:       ctx.font = 'bold 10px Inter, system-ui, sans-serif';
1012:       ctx.textAlign = 'center';
1013:       const text = game.interactLabel;
1014:       const tw = ctx.measureText(text).width + 14;
1015:       ctx.fillStyle = 'rgba(12,9,20,0.82)';
1016:       this.roundRect(ctx, s.x - tw / 2, y - 11, tw, 16, 4);
1017:       ctx.fill();
1018:       ctx.strokeStyle = 'rgba(230,196,106,0.5)';
1019:       ctx.lineWidth = 1;
1020:       this.roundRect(ctx, s.x - tw / 2, y - 11, tw, 16, 4);
1021:       ctx.stroke();
1022:       ctx.fillStyle = '#f2dfa8';
1023:       ctx.fillText(text, s.x, y);
